				Lighting = { Brightness = 2, ClockTime = 11, FogColor = Color3.fromRGB(206, 216, 228), FogStart = 30, FogEnd = 1200 },
				Atmosphere = { Density = 0.55, Haze = 4, Color = Color3.fromRGB(214, 224, 236) },
				Bloom = { Intensity = 0.4, Threshold = 1.2 },
				ColorCorrection = { Contrast = 0.06, Saturation = -0.2, TintColor = Color3.fromRGB(232, 242, 252) },
			},
		},
	}

	function Config.findSky(name)
		for _, sky in ipairs(Config.Skyboxes) do
			if sky.Name == name then
				return sky
			end
		end
		return Config.Skyboxes[1]
	end

	function Config.findPreset(name)
		for _, preset in ipairs(Config.Presets) do
			if preset.Name == name then
				return preset
			end
		end
		return nil
	end

	return Config
end

