				sparkleEmitter = nil
			end
			return
		end
		if not universalSnowPart or not universalSnowPart.Parent then
			ensureUniversalPart()
		end
		if universalSnowEmitter then
			universalSnowEmitter.Enabled = state.toggles.universalSnow == true
			universalSnowEmitter.Rate = particleCap(15 + state.sliders.snowRate * 0.5)
		end
		if sparkleEmitter then
			sparkleEmitter.Enabled = state.toggles.sparkles == true
			sparkleEmitter.Rate = particleCap(8 + state.sliders.sparkleRate * 0.5)
		end
	end

