	local function crownPalette(name, clock)
		if name == "Rainbow" then
			local hue = (clock * 0.12) % 1
			return {
				body = Color3.fromHSV(hue, 0.7, 1),
				trim = Color3.fromHSV(hue, 0.85, 0.72),
				gem = Color3.fromRGB(255, 255, 255),
				light = Color3.fromHSV(hue, 0.35, 1),
			}
		end
		return CROWN_PALETTES[name] or CROWN_PALETTES.Gold
	end

	Effects.getCrownPalette = crownPalette

	function Effects.buildCrownModel(parent, paletteName, scale)
		scale = scale or 1
		local pixel = 0.14 * scale
		local model = Instance.new("Model")
		model.Name = "ShaderVelard_8BitCrown"
		local cells = {}
		local minX, maxX, minZ, maxZ = 0, 0, 0, 0

		local function addCell(x, y, z, role)
			cells[string.format("%d_%d_%d", x, y, z)] = { x = x, y = y, z = z, role = role }
			minX = math.min(minX, x)
			maxX = math.max(maxX, x)
			minZ = math.min(minZ, z)
			maxZ = math.max(maxZ, z)
		end

		for x = -8, 8 do
			for z = -8, 8 do
				local distance = math.sqrt(x * x + z * z)
				if distance >= 5.6 and distance <= 7.1 then
					addCell(x, 0, z, "trim")
					addCell(x, 1, z, "body")
				end
			end
		end

		for index = 0, 7 do
			local angle = math.rad(index * 45)
			local sx = math.round(math.cos(angle) * 6.35)
			local sz = math.round(math.sin(angle) * 6.35)
			local tall = index % 2 == 0
			local top = tall and 4 or 3
			for y = 2, top do
				addCell(sx, y, sz, tall and y == 3 and "gem" or "body")
			end
		end

		for index = 0, 3 do
			local angle = math.rad(index * 90)
			local gx = math.round(math.cos(angle) * 7)
			local gz = math.round(math.sin(angle) * 7)
			addCell(gx, 1, gz, "gem")
		end

		local entries = {}
		local maxY = 0
		for _, cell in pairs(cells) do
			local part = Instance.new("Part")
			part.Name = "CrownVoxel"
			part.Size = Vector3.new(pixel * 1.02, pixel * 1.02, pixel * 1.02)
			part.Position = Vector3.new(cell.x * pixel, cell.y * pixel + pixel * 0.5, cell.z * pixel)
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.CastShadow = false
			part.Material = cell.role == "gem" and Enum.Material.Neon or Enum.Material.SmoothPlastic
			part.Color = Color3.new(1, 1, 1)
			part.Parent = model
			table.insert(entries, { part = part, role = cell.role })
			maxY = math.max(maxY, cell.y)
		end

		local height = (maxY + 1) * pixel
		local width = math.max(maxX - minX + 1, maxZ - minZ + 1) * pixel

		local glowPart = Instance.new("Part")
		glowPart.Name = "CrownGlow"
		glowPart.Size = Vector3.new(0.2, 0.2, 0.2)
		glowPart.Transparency = 1
		glowPart.Anchored = true
		glowPart.CanCollide = false
		glowPart.CanQuery = false
		glowPart.CanTouch = false
		glowPart.CastShadow = false
		glowPart.Position = Vector3.new(0, height * 0.55, 0)
		glowPart.Parent = model

		local glowLight = Instance.new("PointLight")
		glowLight.Name = "CrownGlowLight"
		glowLight.Range = 4 * scale
		glowLight.Brightness = 1.1
		glowLight.Shadows = false
		glowLight.Parent = glowPart

		model.WorldPivot = CFrame.new(0, height * 0.5, 0)
		model.Parent = parent

		local function setPalette(palette)
			for _, entry in ipairs(entries) do
				local color = palette[entry.role] or palette.body
				entry.part.Color = color
			end
			glowLight.Color = palette.light or palette.gem or palette.body
		end

		setPalette(crownPalette(paletteName or "Gold", 0))

		return model, height, width, setPalette
	end

	-- ===== Character cosmetics (Korblox right leg / Headless) =====
	local KORBLOX_MESH_ID = 101851696
	local KORBLOX_TEXTURE_ID = 101851254
	local HEADLESS_HEAD_MESH = "rbxassetid://15093053680"
	local HEADLESS_APPLIED_ATTR = "ShaderVelardHeadlessApplied"
	local HEADLESS_TRANSPARENCY_ATTR = "ShaderVelardHeadOriginalTransparency"
	local HEADLESS_MESH_ATTR = "ShaderVelardHeadOriginalMeshId"
	local HEADLESS_DECAL_ATTR = "ShaderVelardHeadOriginalDecalTransparency"
	-- 8-Bit Royal Crown (classic Roblox limited hat).
	-- Catalog: https://www.roblox.com/catalog/10159600649/8-Bit-Royal-Crown
	local CROWN8BIT_ASSET_ID = 10159600649
	local CROWN8BIT_TEMPLATE_NAME = "8-Bit Royal Crown"

	local function collectCrownGetObjects()
		local loaders = {}
		local seen = {}

		local function add(loader)
			if type(loader) == "function" and not seen[loader] then
				seen[loader] = true
				table.insert(loaders, loader)
			end
		end

		pcall(function()
			local genv = getgenv and getgenv()
			if type(genv) == "table" then
				add(genv.getobjects)
				add(genv.GetObjects)
			end
		end)
		add(rawget(_G, "getobjects"))
		add(rawget(_G, "GetObjects"))

		local ok, gameGetObjects = pcall(function()
			return game.GetObjects
		end)
		if ok and type(gameGetObjects) == "function" then
			add(function(url)
				return game:GetObjects(url)
			end)
		end

		return loaders
	end

	local function stripCrownNonVisual(instance)
		for _, child in ipairs(instance:GetDescendants()) do
			if child:IsA("LuaSourceContainer") or child:IsA("Sound") then
				child:Destroy()
			end
		end
	end

	local function hasCrownVisual(container)
		if container:IsA("BasePart") or container:IsA("Accessory") then
			return true
		end
		for _, child in ipairs(container:GetDescendants()) do
			if child:IsA("BasePart") or child:IsA("Accessory") then
				return true
			end
		end
		return false
	end

	local function loadCrownWithGetObjects()
		local urls = {
			"rbxassetid://" .. CROWN8BIT_ASSET_ID,
			"http://www.roblox.com/asset/?id=" .. CROWN8BIT_ASSET_ID,
			"https://www.roblox.com/asset/?id=" .. CROWN8BIT_ASSET_ID,
			tostring(CROWN8BIT_ASSET_ID),
		}

		for _, loader in ipairs(collectCrownGetObjects()) do
			for _, url in ipairs(urls) do
				local ok, objects = pcall(loader, url)
				if ok and typeof(objects) == "Instance" then
					objects = { objects }
				end
				if ok and type(objects) == "table" and #objects > 0 then
					local holder = Instance.new("Model")
					holder.Name = "ShaderVelard_Crown8BitTemplate"
					for _, object in ipairs(objects) do
						if typeof(object) == "Instance" then
							object.Parent = holder
						end
					end
					if hasCrownVisual(holder) then
						stripCrownNonVisual(holder)
						return holder
					end
					holder:Destroy()
				end
			end
		end

		return nil
	end

	local function collectCosmeticRigs()
		local rigs = {}
		local function add(model)
			if model and typeof(model) == "Instance" and model:IsA("Model") then
				table.insert(rigs, model)
			end
		end

		local currentCharacter = player.Character
		if currentCharacter
			and (currentCharacter:FindFirstChild("Right Leg")
				or currentCharacter:FindFirstChild("RightLeg")
				or currentCharacter:FindFirstChild("RightUpperLeg")) then
			add(currentCharacter)
		end

		local rigsFolder = Workspace:FindFirstChild("Rigs")
		if rigsFolder and rigsFolder:FindFirstChild(player.Name) then
			add(rigsFolder[player.Name])
		end

		local playerCache = Workspace:FindFirstChild("PlayerCache")
		if playerCache and playerCache:FindFirstChild(player.Name) then
			local entry = playerCache[player.Name]
			local r6 = entry and entry:FindFirstChild("R6")
			if r6 then
				add(r6)
			end
		end

		for _, object in ipairs(playerGui:GetDescendants()) do
			if object:IsA("Model") and object.Name == "VisualRigClassic" and object:FindFirstChild("Right Leg") then
				table.insert(rigs, object)
			end
		end

		return rigs
	end

	local function matchRightLegStyle(rig)
		local rightLeg = rig:FindFirstChild("Right Leg") or rig:FindFirstChild("RightLeg")
		local leftLeg = rig:FindFirstChild("Left Leg") or rig:FindFirstChild("LeftLeg")
		if rightLeg and leftLeg and rightLeg:IsA("BasePart") and leftLeg:IsA("BasePart") then
			rightLeg.Color = leftLeg.Color
			rightLeg.Material = leftLeg.Material
			rightLeg.Reflectance = 0
		end
	end

	local function rigUsesR15(rig)
		local humanoid = rig:FindFirstChildOfClass("Humanoid")
		if humanoid then
			return humanoid.RigType == Enum.HumanoidRigType.R15
		end
		return rig:FindFirstChild("RightUpperLeg") ~= nil
	end

	local function applyKorbloxR15(rig)
		local upperLeg = rig:FindFirstChild("RightUpperLeg")
		if not upperLeg or not upperLeg:IsA("BasePart") then
			return false
		end
		local lowerLeg = rig:FindFirstChild("RightLowerLeg")
		local foot = rig:FindFirstChild("RightFoot")

		-- R15 legs are MeshParts, so the R6 CharacterMesh cannot be used.
		-- Hide the real right leg and weld a Korblox mesh in its place.
		for _, part in ipairs({ upperLeg, lowerLeg, foot }) do
			if part and part:IsA("BasePart") then
				if korbloxTransparencyOriginal[part] == nil then
					korbloxTransparencyOriginal[part] = part.Transparency
				end
				part.Transparency = 1
			end
		end

		if rig:FindFirstChild("ShaderVelard_KorbloxLeg") then
			return true
		end

		local upperLen = upperLeg.Size.Y
		local lowerLen = lowerLeg and lowerLeg.Size.Y or upperLen
		local footLen = foot and foot.Size.Y or math.max(upperLen * 0.5, 0.2)
		local totalLen = upperLen + lowerLen + footLen
		local offsetY = -(lowerLen + footLen) / 2

		local legPart = Instance.new("Part")
		legPart.Name = "ShaderVelard_KorbloxLeg"
		legPart.Size = Vector3.new(upperLeg.Size.X, totalLen, upperLeg.Size.Z)
		legPart.CFrame = upperLeg.CFrame * CFrame.new(0, offsetY, 0)
		legPart.Anchored = false
		legPart.CanCollide = false
		legPart.CanQuery = false
		legPart.CanTouch = false
		legPart.CastShadow = false
		legPart.Massless = true
		legPart.Color = Color3.fromRGB(64, 64, 64)
		legPart.Parent = rig

		local mesh = Instance.new("SpecialMesh")
		mesh.Name = "KorbloxMesh"
		mesh.MeshType = Enum.MeshType.FileMesh
		mesh.MeshId = "rbxassetid://" .. KORBLOX_MESH_ID
		mesh.TextureId = "rbxassetid://" .. KORBLOX_TEXTURE_ID
		mesh.Scale = Vector3.new(1, totalLen / 2, 1)
		mesh.Parent = legPart

		local weld = Instance.new("Weld")
		weld.Name = "KorbloxWeld"
		weld.Part0 = upperLeg
		weld.Part1 = legPart
		weld.C0 = CFrame.new(0, offsetY, 0)
		weld.Parent = legPart

		return true
	end

	local function applyKorbloxLeg(rig)
		if rigUsesR15(rig) then
			return applyKorbloxR15(rig)
		end

		matchRightLegStyle(rig)
		for _, child in ipairs(rig:GetChildren()) do
			if child:IsA("CharacterMesh")
				and child.BodyPart == Enum.BodyPart.RightLeg
				and child.MeshId == KORBLOX_MESH_ID then
				return true
			end
		end
		local mesh = Instance.new("CharacterMesh")
		mesh.Name = "ShaderVelard_KorbloxRightLeg"
		mesh.BodyPart = Enum.BodyPart.RightLeg
		mesh.MeshId = KORBLOX_MESH_ID
		mesh.OverlayTextureId = KORBLOX_TEXTURE_ID
		mesh.Parent = rig
		return true
	end

	local function clearKorbloxLeg(rig)
		local welded = rig:FindFirstChild("ShaderVelard_KorbloxLeg")
		if welded then
			welded:Destroy()
		end
		for _, name in ipairs({ "RightUpperLeg", "RightLowerLeg", "RightFoot" }) do
			local part = rig:FindFirstChild(name)
			if part and part:IsA("BasePart") and korbloxTransparencyOriginal[part] ~= nil then
				part.Transparency = korbloxTransparencyOriginal[part]
				korbloxTransparencyOriginal[part] = nil
			end
		end

		for _, child in ipairs(rig:GetChildren()) do
			if child:IsA("CharacterMesh")
				and child.BodyPart == Enum.BodyPart.RightLeg
				and (child.MeshId == KORBLOX_MESH_ID or string.find(child.Name:lower(), "korblox", 1, true)) then
				child:Destroy()
			end
		end
	end

	local function applyHeadlessHead(rig)
		local head = rig:FindFirstChild("Head")
		if not head or not head:IsA("BasePart") then
			return false
		end

		if head:GetAttribute(HEADLESS_APPLIED_ATTR) ~= true then
			head:SetAttribute(HEADLESS_APPLIED_ATTR, true)
			head:SetAttribute(HEADLESS_TRANSPARENCY_ATTR, head.Transparency)
			if not head:IsA("MeshPart") then
				local specialMesh = head:FindFirstChildOfClass("SpecialMesh")
				if specialMesh then
					specialMesh:SetAttribute(HEADLESS_MESH_ATTR, specialMesh.MeshId)
				end
			end
			for _, child in ipairs(head:GetChildren()) do
				if child:IsA("Decal") then
					child:SetAttribute(HEADLESS_DECAL_ATTR, child.Transparency)
				end
			end
		end

		head.Transparency = 1
		if not head:IsA("MeshPart") then
			local specialMesh = head:FindFirstChildOfClass("SpecialMesh")
			if specialMesh then
				specialMesh.MeshId = HEADLESS_HEAD_MESH
			end
		end

		for _, child in ipairs(head:GetChildren()) do
			if child:IsA("Decal") then
				child.Transparency = 1
			end
		end
		return true
	end

	local function clearHeadlessHead(rig)
		local head = rig:FindFirstChild("Head")
		if not head or not head:IsA("BasePart") then
			return
		end

		local applied = head:GetAttribute(HEADLESS_APPLIED_ATTR) == true
		local originalTransparency = head:GetAttribute(HEADLESS_TRANSPARENCY_ATTR)
		if originalTransparency ~= nil then
			head.Transparency = originalTransparency
		elseif applied then
			head.Transparency = 0
		end

		if not head:IsA("MeshPart") then
			local specialMesh = head:FindFirstChildOfClass("SpecialMesh")
			if specialMesh then
				local originalMesh = specialMesh:GetAttribute(HEADLESS_MESH_ATTR)
				if originalMesh ~= nil then
					specialMesh.MeshId = originalMesh
					specialMesh:SetAttribute(HEADLESS_MESH_ATTR, nil)
				elseif specialMesh.MeshId == HEADLESS_HEAD_MESH then
					specialMesh.MeshId = ""
				end
			end
		end

		for _, child in ipairs(head:GetChildren()) do
			if child:IsA("Decal") then
				local original = child:GetAttribute(HEADLESS_DECAL_ATTR)
				if original ~= nil then
					child.Transparency = original
					child:SetAttribute(HEADLESS_DECAL_ATTR, nil)
				elseif applied then
					child.Transparency = 0
				end
			end
		end

		head:SetAttribute(HEADLESS_APPLIED_ATTR, nil)
		head:SetAttribute(HEADLESS_TRANSPARENCY_ATTR, nil)
	end

	local function applyKorblox()
		local applied = 0
		for _, rig in ipairs(collectCosmeticRigs()) do
			local ok, result = pcall(applyKorbloxLeg, rig)
			if ok and result then
				applied = applied + 1
			end
		end
		return applied
	end

	local function clearKorblox()
		for _, rig in ipairs(collectCosmeticRigs()) do
			pcall(clearKorbloxLeg, rig)
		end
	end

	local function notifyKorbloxUnsupported()
		local message = "Korblox hanya berfungsi di rig R6/R15."
		if Effects.onNotify then
			pcall(Effects.onNotify, "ShaderVelard", message, 4)
		end
		setStatus(message)
	end

	local function applyHeadless()
		for _, rig in ipairs(collectCosmeticRigs()) do
			pcall(applyHeadlessHead, rig)
		end
	end

	local function clearHeadless()
		for _, rig in ipairs(collectCosmeticRigs()) do
			pcall(clearHeadlessHead, rig)
		end
	end

	-- ===== 8-Bit Crown (real Roblox UGC asset, client-side visual) =====
	local crownAssetTemplate = nil
	local crownAccessory = nil
	local crownLoadRetryAt = 0

	local function destroyCrown()
		if crownAccessory then
			pcall(function()
				crownAccessory:Destroy()
			end)
			crownAccessory = nil
		end
	end

	local function fetchCrownAsset()
		local fromGetObjects = loadCrownWithGetObjects()
		if fromGetObjects then
			return fromGetObjects
		end

		local ok, result = pcall(function()
			return game:GetService("InsertService"):LoadAsset(CROWN8BIT_ASSET_ID)
		end)
		if ok and result then
			stripCrownNonVisual(result)
			return result
		end

		return nil
	end

	local function getCrownCacheFolder()
		local cache = ReplicatedStorage:FindFirstChild("ShaderVelardCrownCache")
		if not cache then
			cache = Instance.new("Folder")
			cache.Name = "ShaderVelardCrownCache"
			cache.Parent = ReplicatedStorage
		end
		return cache
	end

	local function findCrownTemplateInWorld()
		for _, root in ipairs({ Workspace, ReplicatedStorage }) do
			local found = root:FindFirstChild(CROWN8BIT_TEMPLATE_NAME, true)
			if found then
				return found
			end
		end
		return nil
	end

	local function takeCrownTemplateFromWorld()
		local found = findCrownTemplateInWorld()
		if not found then
			return nil
		end

		local cloned = found:Clone()
		if not cloned then
			return nil
		end

		stripCrownNonVisual(cloned)

		if found:IsDescendantOf(Workspace) then
			pcall(function()
				found.Parent = getCrownCacheFolder()
			end)
		end

		return cloned
	end

	local function loadCrownTemplate()
		if crownAssetTemplate then
			return crownAssetTemplate
		end
		if os.clock() < crownLoadRetryAt then
			return nil
		end

		local worldTemplate = takeCrownTemplateFromWorld()
		if worldTemplate then
			worldTemplate.Name = "ShaderVelard_Crown8BitTemplate"
			crownAssetTemplate = worldTemplate
			return worldTemplate
		end

		local result = fetchCrownAsset()
		if not result then
			crownLoadRetryAt = os.clock() + 10
			warn("[ShaderVelard] 8-Bit Crown asset load failed")
			return nil
		end

		result.Name = "ShaderVelard_Crown8BitTemplate"
		crownAssetTemplate = result
		return result
	end

	local function findCrownAccessory(container)
		if container:IsA("Accessory") then
			return container
		end
		for _, item in ipairs(container:GetDescendants()) do
			if item:IsA("Accessory") then
				return item
			end
		end
		return nil
	end

	local function weldCrownHandle(container, head)
		local handle = container
		if not handle:IsA("BasePart") then
			handle = container:FindFirstChild("Handle", true)
		end
		if not handle or not handle:IsA("BasePart") then
			return false
		end
		local hatAttachment = handle:FindFirstChild("HatAttachment")
			or handle:FindFirstChildWhichIsA("Attachment")
		local headAttachment = head:FindFirstChild("HatAttachment")
		if not headAttachment then
			headAttachment = Instance.new("Attachment")
			headAttachment.Name = "HatAttachment"
			headAttachment.Position = Vector3.new(0, head.Size.Y * 0.5, 0)
			headAttachment.Parent = head
		end
		if not hatAttachment then
			local mesh = handle:FindFirstChildOfClass("SpecialMesh")
			local scaleY = mesh and mesh.Scale.Y or 1
			hatAttachment = Instance.new("Attachment")
			hatAttachment.Name = "HatAttachment"
			hatAttachment.Position = Vector3.new(0, -handle.Size.Y * 0.5 * scaleY, 0)
			hatAttachment.Parent = handle
		end

		handle.Anchored = false
		handle.CanCollide = false
		handle.CanQuery = false
		handle.CanTouch = false
		handle.Massless = true
		handle.CFrame = headAttachment.WorldCFrame * hatAttachment.CFrame:Inverse()

		local weld = Instance.new("Weld")
		weld.Name = "ShaderVelard_CrownWeld"
		weld.Part0 = head
		weld.Part1 = handle
		weld.C0 = headAttachment.CFrame * hatAttachment.CFrame:Inverse()
		weld.Parent = handle
		return true
	end

	-- Adds the signature shimmer/sparkle the original 8-Bit Royal Crown has.
	local function decorateCrownSparkles(container)
		if not container then
			return
		end
		local handle = container
		if not handle:IsA("BasePart") then
			handle = container:FindFirstChild("Handle", true) or container:FindFirstChildWhichIsA("BasePart", true)
		end
		if not handle or not handle:IsA("BasePart") then
			return
		end
		if handle:FindFirstChild("ShaderVelard_CrownSparkle") then
			return
		end

		local emitter = Instance.new("ParticleEmitter")
		emitter.Name = "ShaderVelard_CrownSparkle"
		emitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		emitter.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 236, 170)),
			ColorSequenceKeypoint.new(0.6, Color3.fromRGB(255, 214, 120)),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
		})
		emitter.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 1),
			NumberSequenceKeypoint.new(0.15, 0.2),
			NumberSequenceKeypoint.new(0.8, 0.35),
			NumberSequenceKeypoint.new(1, 1),
		})
		emitter.Size = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.18),
			NumberSequenceKeypoint.new(1, 0),
		})
		emitter.Lifetime = NumberRange.new(0.5, 1.1)
		emitter.Rate = 8
		emitter.Speed = NumberRange.new(0.4, 1.1)
		emitter.SpreadAngle = Vector2.new(180, 180)
		emitter.Rotation = NumberRange.new(0, 360)
		emitter.RotSpeed = NumberRange.new(-60, 60)
		emitter.LightEmission = 0.9
		emitter.LightInfluence = 0
		emitter.Acceleration = Vector3.new(0, 1.4, 0)
		emitter.Enabled = true
		emitter.Parent = handle

		local glow = Instance.new("PointLight")
		glow.Name = "ShaderVelard_CrownGlow"
		glow.Color = Color3.fromRGB(255, 224, 150)
		glow.Brightness = 1.2
		glow.Range = 5
		glow.Shadows = false
		glow.Parent = handle
	end

	local function ensureCrown()
		local currentCharacter = player.Character
		local head = currentCharacter and currentCharacter:FindFirstChild("Head")
		local humanoid = currentCharacter and currentCharacter:FindFirstChildOfClass("Humanoid")
		if not head or not head:IsA("BasePart") or not humanoid then
			return nil
		end

		if crownAccessory
			and crownAccessory.Parent == currentCharacter
			and (crownAccessory:IsA("BasePart") or crownAccessory:FindFirstChild("Handle")) then
			return true
		end

		destroyCrown()

		local template = loadCrownTemplate()
		if not template then
			return false
		end

		local templateAccessory = findCrownAccessory(template)
		if templateAccessory then
			local accessory = templateAccessory:Clone()
			accessory.Name = "ShaderVelard_Crown8Bit"
			crownAccessory = accessory

			local attached = pcall(function()
				humanoid:AddAccessory(accessory)
			end)
			if attached and accessory.Parent then
				decorateCrownSparkles(accessory)
				return true
			end

			accessory.Parent = currentCharacter
			if weldCrownHandle(accessory, head) then
				decorateCrownSparkles(accessory)
				return true
			end
			destroyCrown()
			return false
		end

		local templateHandle
		if template:IsA("BasePart") then
			templateHandle = template
		else
			templateHandle = template:FindFirstChild("Handle", true)
				or template:FindFirstChildWhichIsA("BasePart", true)
		end
		if not templateHandle or not templateHandle:IsA("BasePart") then
			warn("[ShaderVelard] 8-Bit Crown asset has no handle")
			return false
		end

		local clone
		local handle
		if template:IsA("BasePart") then
			clone = template:Clone()
			handle = clone
		else
			clone = template:Clone()
			handle = clone and (clone:FindFirstChild(templateHandle.Name, true)
				or clone:FindFirstChildWhichIsA("BasePart", true))
		end
		if not clone or not handle then
			warn("[ShaderVelard] 8-Bit Crown asset has no handle")
			return false
		end

		crownAccessory = clone
		clone.Parent = currentCharacter
		if weldCrownHandle(handle, head) then
			decorateCrownSparkles(clone)
			return true
		end
		destroyCrown()
		return false
	end

	local function notifyCrownUnsupported()
		local message = "8-Bit Crown gagal dimuat. Taruh model \"8-Bit Royal Crown\" dari Toolbox di Workspace, atau pakai executor yang mendukung GetObjects."
		if Effects.onNotify then
			pcall(Effects.onNotify, "ShaderVelard", message, 4)
		end
		setStatus(message)
	end

	local function applyCosmetics()
		if state.toggles.korblox then
			applyKorblox()
		end
		if state.toggles.headless then
			applyHeadless()
		end
		if state.toggles.crown8bit then
			ensureCrown()
		end
	end

	local function clearCosmetics()
		clearKorblox()
		clearHeadless()
		destroyCrown()
	end

	local function resetCosmeticCache()
		korbloxTransparencyOriginal = {}
	end

	if characterConnection then
		characterConnection:Disconnect()
	end
	characterConnection = player.CharacterAdded:Connect(function()
		task.wait(0.5)
		pcall(clearKorblox)
		pcall(clearHeadless)
		resetCosmeticCache()
		pcall(function()
			if state.toggles.angelAura then
				ensureAura()
			end
			if state.toggles.motionTrail then
				ensureTrail()
			end
		end)
		pcall(applyCosmetics)
	end)

	local function syncAllWorld()
		syncReflectionFloors()
		refreshCelHighlights()
		refreshNeon()
		syncClouds()
		syncWindVFX()
		if state.toggles.disco then
			ensureDisco()
		else
			clearDisco()
		end
		if not state.toggles.wind then
			safeSet(Workspace, "GlobalWind", globalWindOriginal)
		end
		updateVignette()
		updateLetterbox()
		updateChromatic()
		updateRain()
		updateScanlines()
		updateFlare()
		updateMotion()
		updateVhs()
		updateReShade()
		updateSnow()
		updateWatermark()
		local okFeatures, featureError = pcall(function()
			if state.toggles.angelAura then
				ensureAura()
			else
				clearAura()
			end
			if state.toggles.motionTrail then
				ensureTrail()
			else
				clearTrail()
			end
			if state.toggles.skyText then
				ensureSkyText()
			else
				clearSkyText()
			end
			updateUniversalParticles()
			if state.toggles.korblox then
				applyKorblox()
			else
				clearKorblox()
			end
			if state.toggles.headless then
				applyHeadless()
			else
				clearHeadless()
			end
			if state.toggles.crown8bit then
				ensureCrown()
			else
				destroyCrown()
			end
		end)
		if not okFeatures then
			warn("[ShaderVelard] world feature sync failed: " .. tostring(featureError))
		end
	end

	local function startLightning()
		lightningToken = lightningToken + 1
		local token = lightningToken
		task.spawn(function()
			while state.toggles.lightning and token == lightningToken do
				local frequency = math.clamp(state.sliders.lightningFrequency or 1, 0.2, 3)
				task.wait((math.random(35, 75) / 10) / frequency)
				if not state.toggles.lightning or token ~= lightningToken then
					break
				end
				local palette = state.dropdowns.lightningPalette or "White"
				local flashColor
				if palette == "Blue" then
					flashColor = Color3.fromRGB(180, 205, 255)
				elseif palette == "Purple" then
					flashColor = Color3.fromRGB(206, 180, 255)
				elseif palette == "Multi" then
					flashColor = Color3.fromHSV(math.random(), 0.6, 1)
				else
					flashColor = Color3.fromRGB(215, 228, 255)
				end
				local bloom = ensurePost("Bloom")
				local bloomIntensity = 0
				if bloom then
					local ok, value = pcall(function()
						return bloom.Intensity
					end)
					if ok and type(value) == "number" then
						bloomIntensity = value
					end
				end
				local brightness = Lighting.Brightness
				local ambient = Lighting.Ambient
				safeSet(Lighting, "Brightness", brightness + 3)
				safeSet(Lighting, "Ambient", flashColor)
				if bloom then
					safeSet(bloom, "Intensity", bloomIntensity + 1.5)
				end
				task.wait(0.06)
				Effects.recompute()
				task.wait(0.07)
				if not state.toggles.lightning or token ~= lightningToken then
					break
				end
				safeSet(Lighting, "Brightness", brightness + 1.8)
				if bloom then
					safeSet(bloom, "Intensity", bloomIntensity + 0.8)
				end
				task.wait(0.045)
				Effects.recompute()
				safeSet(Lighting, "Ambient", ambient)
			end
		end)
	end

	function Effects.setToggle(name, value)
		if state.toggles[name] == value then
			return
		end
		state.toggles[name] = value

		local applied, applyError = pcall(function()
		if name == "wetFloor" or name == "ssr" or name == "banano" or name == "rtx" then
			syncReflectionFloors()
		elseif name == "celShading" then
			refreshCelHighlights()
		elseif name == "neon" then
			refreshNeon()
		elseif name == "clouds" then
			syncClouds()
		elseif name == "windVFX" then
			syncWindVFX()
		elseif name == "disco" then
			if value then
				ensureDisco()
			else
				clearDisco()
			end
		elseif name == "discoAura" then
			if not value and discoAuraLight then
				discoAuraLight:Destroy()
				discoAuraLight = nil
			end
		elseif name == "wind" then
			if not value then
				safeSet(Workspace, "GlobalWind", globalWindOriginal)
			end
		elseif name == "rain" then
			updateRain()
		elseif name == "nightVision" then
			updateScanlines()
		elseif name == "lensFlare" then
			updateFlare()
		elseif name == "vignette" then
			updateVignette()
		elseif name == "letterbox" then
			updateLetterbox()
		elseif name == "chromatic" then
			updateChromatic()
		elseif name == "motionBlur" then
			updateMotion()
		elseif name == "vhs" then
			updateVhs()
		elseif name == "reShade" then
			updateReShade()
		elseif name == "winterTerrain" then
			updateSnow()
		elseif name == "watermark" then
			updateWatermark()
		elseif name == "hideSun" then
			syncSky()
		elseif name == "lightning" then
			if value then
				startLightning()
			else
				lightningToken = lightningToken + 1
				Effects.recompute()
			end
		elseif name == "angelAura" then
			if value then
				ensureAura()
			else
				clearAura()
			end
		elseif name == "motionTrail" then
			if value then
				ensureTrail()
			else
				clearTrail()
			end
		elseif name == "skyText" then
			if value then
				ensureSkyText()
			else
				clearSkyText()
			end
		elseif name == "korblox" then
			if value then
				if applyKorblox() == 0 then
					notifyKorbloxUnsupported()
				end
			else
				clearKorblox()
			end
		elseif name == "headless" then
			if value then
				applyHeadless()
			else
				clearHeadless()
			end
		elseif name == "crown8bit" then
			if value then
				if ensureCrown() == false then
					state.toggles.crown8bit = false
					notifyCrownUnsupported()
				end
			else
				destroyCrown()
			end
		elseif name == "universalSnow" or name == "sparkles" then
			updateUniversalParticles()
		elseif name == "skyAnimation" then
			skyTimer = 0
		end
		end)
		if not applied then
			warn("[ShaderVelard] toggle '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end

		if name == "nightVision"
			or name == "monochrome"
			or name == "celShading"
			or name == "greenScreen"
			or name == "fakeSSAO"
			or name == "hideSun"
			or name == "lightning"
			or name == "bokeh"
			or name == "vhs"
			or name == "reShade"
			or name == "winterTerrain"
			or name == "evadeLighting"
			or name == "disco"
			or name == "discoBloom"
			or name == "rainbow"
			or name == "policeFlash" then
			Effects.recompute()
		end

		notifyChanged()
		setStatus((value and "Enabled " or "Disabled ") .. name)
	end

	function Effects.setSlider(name, value)
		state.sliders[name] = value

		local applied, applyError = pcall(function()
		if name == "brightness" then
			state.base.Lighting.Brightness = value
		elseif name == "exposure" then
			state.base.Lighting.ExposureCompensation = value
		elseif name == "bloom" then
			state.base.Bloom.Intensity = value
		elseif name == "saturation" then
			state.base.ColorCorrection.Saturation = value
		elseif name == "contrast" then
			state.base.ColorCorrection.Contrast = value
		elseif name == "fogDensity" then
			state.base.Atmosphere.Density = value
		elseif name == "fov" then
			local camera = Workspace.CurrentCamera
			if camera then
				camera.FieldOfView = value
			end
			return
		elseif name == "vignette" then
			updateVignette()
			return
		elseif name == "chromaticStrength" then
			updateChromatic()
			return
		elseif name == "rainIntensity" then
			updateRain()
			return
		elseif name == "cloudCover" then
			syncClouds()
			return
		elseif name == "glossyReflectance" or name == "ssrDetail" or name == "ssrOpacity"
			or name == "bananoLevel" or name == "rtxLevel" then
			applyGlossy()
			return
		elseif name == "bananoRadius" or name == "bananoOffset"
			or name == "rtxRadius" or name == "rtxOffset" then
			refreshGlossy()
			return
		elseif name == "motionBlurStrength" or name == "windStrength" or name == "discoSpeed"
			or name == "skySpeed" or name == "cloudSpeed" or name == "lightningFrequency"
			or name == "snowIntensity" then
			return
		elseif name == "reShadeIntensity" then
			updateReShade()
			Effects.recompute()
			return
		elseif name == "vhsIntensity" then
			updateVhs()
			return
		elseif name == "neonIntensity" then
			for _, highlight in pairs(neonHighlights) do
				if highlight and highlight.Parent then
					highlight.OutlineTransparency = math.clamp(0.3 - state.sliders.neonIntensity * 0.25, 0, 0.8)
				end
			end
			return
		elseif name == "discoIntensity" then
			Effects.recompute()
			return
		elseif name == "bokehFocus" or name == "bokehIntensity" then
			if state.toggles.bokeh then
				Effects.recompute()
			end
			return
		elseif name == "auraSize" or name == "auraSpeed" then
			updateAuraStyle()
			return
		elseif name == "trailLifetime" then
			updateTrailStyle()
			return
		elseif name == "skyTextSize" or name == "skyTextThickness" then
			updateSkyTextStyle()
			return
		elseif name == "sparkleRate" or name == "snowRate" then
			updateUniversalParticles()
			return
		elseif name == "skyTextHeight" or name == "skyTextDistance" or name == "skyTextAnimSpeed"
			or name == "rainbowSpeed" or name == "policeFlashSpeed" then
			return
		end
		end)
		if not applied then
			warn("[ShaderVelard] slider '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end

		Effects.recompute()
	end

	function Effects.setDropdown(name, value)
		if state.dropdowns[name] == value then
			return
		end
		state.dropdowns[name] = value

		local applied, applyError = pcall(function()
		if name == "glossyMode" then
			applyGlossy()
		elseif name == "sunTint" then
			Effects.recompute()
		elseif name == "discoMode" or name == "lightningPalette" then
			return
		elseif name == "auraColor" then
			updateAuraStyle()
		elseif name == "trailColor" then
			updateTrailStyle()
		elseif name == "skyTextColor" then
			updateSkyTextStyle()
		elseif name == "skyTextAnim" then
			return
		end
		end)
		if not applied then
			warn("[ShaderVelard] dropdown '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end

		notifyChanged()
		setStatus("Set " .. name .. " to " .. tostring(value))
	end

	function Effects.setSkyText(text)
		text = tostring(text or "")
		if #text > 80 then
			text = string.sub(text, 1, 80)
		end
		state.skyTextString = text
		local ok, err = pcall(function()
			if skyTextLabel then
				skyTextLabel.Text = text
			end
		end)
		if not ok then
			warn("[ShaderVelard] sky text update failed: " .. tostring(err))
		end
		setStatus("Sky text updated")
		return text
	end

	function Effects.applyPreset(name)
		local preset = Config.findPreset(name)
		if not preset then
			return
		end

		local look = copy(Config.NeutralLook)
		merge(look, preset.Look)
		state.base = look
		state.presetName = preset.Name

		for key in pairs(state.toggles) do
			state.toggles[key] = false
		end
		state.dropdowns = copy(initialDropdowns)

		state.sliders.brightness = math.clamp(look.Lighting.Brightness, 0, 5)
		state.sliders.exposure = math.clamp(look.Lighting.ExposureCompensation, -2, 2)
		state.sliders.bloom = math.clamp(look.Bloom.Intensity, 0, 5)
		state.sliders.saturation = math.clamp(look.ColorCorrection.Saturation, -1, 1)
		state.sliders.contrast = math.clamp(look.ColorCorrection.Contrast, -1, 1)
		state.sliders.fogDensity = math.clamp(look.Atmosphere.Density, 0, 1)

		if preset.Sliders then
			for key, value in pairs(preset.Sliders) do
				state.sliders[key] = value
			end
		end
		if preset.Dropdowns then
			for key, value in pairs(preset.Dropdowns) do
				state.dropdowns[key] = value
			end
		end
		state.base.ColorCorrection.Saturation = math.clamp(state.sliders.saturation, -1, 1)
		state.base.ColorCorrection.Contrast = math.clamp(state.sliders.contrast, -1, 1)
		lightningToken = lightningToken + 1
		if preset.Toggles then
			for key, value in pairs(preset.Toggles) do
				state.toggles[key] = value
			end
			if preset.Toggles.skyAnimation then
				skyTimer = 0
			end
			if preset.Toggles.lightning then
				startLightning()
			end
		end

		if preset.Sky then
			Effects.applySky(preset.Sky)
		end

		local applied, applyError = pcall(function()
			syncAllWorld()
			Effects.recompute()
		end)
		if not applied then
			warn("[ShaderVelard] preset '" .. tostring(name) .. "' failed: " .. tostring(applyError))
		end
		notifyChanged()
		setStatus("Applied preset: " .. preset.Name)
	end

	function Effects.resetAll()
		lightningToken = lightningToken + 1
		state.toggles = {
			wetFloor = false,
			ssr = false,
			vignette = false,
			letterbox = false,
			chromatic = false,
			nightVision = false,
			monochrome = false,
			celShading = false,
			greenScreen = false,
			lensFlare = false,
			fakeSSAO = false,
			hideSun = false,
			rain = false,
			clouds = false,
			lightning = false,
			wind = false,
			disco = false,
			discoBloom = false,
			discoAura = false,
			skyAnimation = false,
			bokeh = false,
			motionBlur = false,
			vhs = false,
			reShade = false,
			watermark = false,
			neon = false,
			evadeLighting = false,
			winterTerrain = false,
			windVFX = false,
			banano = false,
			rtx = false,
			angelAura = false,
			motionTrail = false,
			skyText = false,
			universalSnow = false,
			sparkles = false,
			rainbow = false,
			policeFlash = false,
			korblox = false,
			headless = false,
			crown8bit = false,
		}

		clearGlossy()
		clearCelHighlights()
		clearNeon()
		clearDisco()
		if discoAuraLight then
			discoAuraLight:Destroy()
			discoAuraLight = nil
		end
		clearAura()
		clearTrail()
		clearSkyText()
		clearCosmetics()
		resetCosmeticCache()
		if universalSnowPart then
			universalSnowPart:Destroy()
			universalSnowPart = nil
			universalSnowEmitter = nil
			sparkleEmitter = nil
		end
		syncWindVFX()
		clearClouds()
		restoreTerrain()

		for key, value in pairs(lightingOriginal) do
			safeSet(Lighting, key, value)
		end

		for _, post in ipairs(POST_CLASSES) do
			local entry = posts[post.key]
			if entry then
				if entry.created then
					if entry.instance and entry.instance.Parent then
						entry.instance:Destroy()
					end
					posts[post.key] = nil
				else
					for key, value in pairs(entry.props) do
						safeSet(entry.instance, key, value)
					end
				end
			end
		end

		if skyInstance then
			if skyWasCreated then
				skyInstance:Destroy()
				skyInstance = nil
				skyWasCreated = false
			elseif skyOriginal then
				for key, value in pairs(skyOriginal) do
					safeSet(skyInstance, key, value)
				end
			end
		end

		local camera = Workspace.CurrentCamera
		if camera then
			safeSet(camera, "FieldOfView", initialFov)
		end

		state.base = copy(initialBase)
		state.sliders = copy(initialSliders)
		state.dropdowns = copy(initialDropdowns)
		state.presetName = "None"
		state.skyName = "Default"
		state.skyIndex = 1

		vignetteContainer.Visible = false
		letterboxTop.Visible = false
		letterboxBottom.Visible = false
		chromaticContainer.Visible = false
		scanlineContainer.Visible = false
		rainContainer.Visible = false
		flareContainer.Visible = false
		motionContainer.Visible = false
		vhsContainer.Visible = false
		reShadeContainer.Visible = false
		snowContainer.Visible = false
		watermarkLabel.Visible = false
		if discoPart then
			discoPart:Destroy()
			discoPart = nil
		end
		if discoAuraLight then
			discoAuraLight:Destroy()
			discoAuraLight = nil
		end

		notifyChanged()
		setStatus("All shader effects reset")
	end

	function Effects.setLiteMode(value)
		state.liteMode = value == true
		if state.toggles.wetFloor or state.toggles.ssr or state.toggles.banano or state.toggles.rtx then
			applyGlossy()
		end
		if state.toggles.neon then
			refreshNeon()
		end
		if state.toggles.celShading then
			refreshCelHighlights()
		end
		if state.toggles.universalSnow or state.toggles.sparkles then
			updateUniversalParticles()
		end
		if state.toggles.angelAura then
			updateAuraStyle()
		end
		setStatus("Lite Mode " .. (state.liteMode and "enabled" or "disabled"))
		notifyChanged()
		return state.liteMode
	end

	function Effects.destroy()
		if Effects._destroyed then
			return
		end
		Effects._destroyed = true
		Effects.onChanged = nil
		Effects.onStatus = nil
		Effects.onNotify = nil
		Effects.onSkyChanged = nil
		lightningToken = lightningToken + 1
		if stepConnection then
			stepConnection:Disconnect()
			stepConnection = nil
		end
		if characterConnection then
			characterConnection:Disconnect()
			characterConnection = nil
		end
		Effects.resetAll()
		if overlay and overlay.Parent then
			overlay:Destroy()
		end
		overlay = nil
	end

	function Effects.getPresetNames()
		local names = {}
		for _, preset in ipairs(Config.Presets) do
			table.insert(names, preset.Name)
		end
		return names
	end

	function Effects.getSkyNames()
		local names = {}
		for _, sky in ipairs(Config.Skyboxes) do
			table.insert(names, sky.Name)
		end
		return names
	end

	local stepErrorLogged = false
	stepConnection = RunService.RenderStepped:Connect(function(deltaTime)
		local ok, err = pcall(function()
		clock = clock + deltaTime

		if state.toggles.skyAnimation then
			skyTimer = skyTimer + deltaTime
			if skyTimer >= state.sliders.skySpeed then
				skyTimer = 0
				advanceSky()
			end
		end

		if state.toggles.korblox or state.toggles.headless or state.toggles.crown8bit then
			cosmeticTimer = cosmeticTimer + deltaTime
			if cosmeticTimer >= 1.5 then
				cosmeticTimer = 0
				applyCosmetics()
			end
		else
			cosmeticTimer = 0
		end

		if state.toggles.chromatic then
			local strength = state.sliders.chromaticStrength
			local offset = math.sin(clock * 3.2) * math.clamp(strength, 0, 3) * 2
			local thickness = chromaticLeft.AbsoluteSize.X
			chromaticLeft.Position = UDim2.new(0, -offset, 0, 0)
			chromaticRight.Position = UDim2.new(1, -thickness + offset, 0, 0)
		end

		if state.toggles.rain then
			local intensity = math.clamp(state.sliders.rainIntensity / 100, 0.1, 1)
			local viewport = overlay.AbsoluteSize.Y
			for _, drop in ipairs(rainStreaks) do
				drop.y = drop.y + (drop.speed * intensity * deltaTime) / math.max(viewport, 1)
				if drop.y > 1.1 then
					drop.y = -0.12
					drop.x = math.random()
				end
				drop.frame.Position = UDim2.new(drop.x, 0, drop.y, 0)
			end
		end

		if state.toggles.lensFlare then
			local camera = Workspace.CurrentCamera
			if camera then
				local sunDirection = Lighting:GetSunDirection()
				local worldPoint = camera.CFrame.Position + sunDirection * 1200
				local screenPoint, onScreen = camera:WorldToViewportPoint(worldPoint)
				if onScreen and screenPoint.Z > 0 then
					flareContainer.Visible = true
					local pos = UDim2.fromOffset(screenPoint.X, screenPoint.Y)
					flareOuter.Position = pos
					flareMid.Position = pos + UDim2.fromOffset(26, -18)
					flareCore.Position = pos
					local pulse = 0.9 + math.sin(clock * 1.7) * 0.06
					flareOuter.Size = UDim2.fromOffset(180 * pulse, 180 * pulse)
					flareMid.Size = UDim2.fromOffset(76 * pulse, 76 * pulse)
				else
					flareContainer.Visible = false
				end
			end
		end

		if state.toggles.disco then
			local camera = Workspace.CurrentCamera
			if not discoPart or not discoPart.Parent then
				ensureDisco()
			end
			local intensity = state.sliders.discoIntensity
			local mode = state.dropdowns.discoMode
			if discoPart and camera then
				discoPart.CFrame = camera.CFrame * CFrame.new(0, 5, -8)
				for index, light in ipairs(discoLights) do
					if light and light.Parent then
						local hue
						if mode == "Warm Pulse" then
							hue = 0.06 + math.sin(clock * 2 + index) * 0.04
						elseif mode == "Cool Pulse" then
							hue = 0.55 + math.sin(clock * 2 + index) * 0.05
						elseif mode == "Strobe" then
							hue = (index % 2 == 0) and 0 or 0.66
						else
							hue = (clock * 0.18 * state.sliders.discoSpeed + index / 3) % 1
						end
						light.Color = Color3.fromHSV((hue % 1 + 1) % 1, 0.85, 1)
						light.Brightness = intensity * (0.8 + math.sin(clock * 3 + index) * 0.25)
						light.Range = 22 + intensity * 1.6 + math.sin(clock * 2 + index) * 5
					end
				end
			end

			if state.toggles.discoAura then
				local character = player.Character
				local root = character and character:FindFirstChild("HumanoidRootPart")
				if root then
					if not discoAuraLight or not discoAuraLight.Parent then
						discoAuraLight = Instance.new("PointLight")
						discoAuraLight.Name = "ShaderVelard_DiscoAura"
						discoAuraLight.Range = 14
						discoAuraLight.Shadows = false
						discoAuraLight.Parent = root
					end
					local auraHue = (clock * 0.2 * state.sliders.discoSpeed) % 1
					discoAuraLight.Color = Color3.fromHSV(auraHue, 0.8, 1)
					discoAuraLight.Brightness = intensity * 0.6
				end
			elseif discoAuraLight then
				discoAuraLight:Destroy()
				discoAuraLight = nil
			end
		end

		if state.toggles.clouds then
			local clouds = terrain:FindFirstChildOfClass("Clouds")
			if clouds then
				local speed = state.sliders.cloudSpeed
				local cover = math.clamp(state.sliders.cloudCover + math.sin(clock * 0.07 * speed) * 0.12, 0.05, 1)
				safeSet(clouds, "Cover", cover)
			end
		end

		if state.toggles.wind then
			local strength = state.sliders.windStrength / 100
			local wind = Vector3.new(
				math.sin(clock * 0.35) * 18 * strength,
				math.sin(clock * 0.21) * 3 * strength,
				math.cos(clock * 0.28) * 18 * strength
			)
			safeSet(Workspace, "GlobalWind", wind)
		end

		local camera = Workspace.CurrentCamera
		if camera then
			local look = camera.CFrame.LookVector
			if lastCameraLook then
				local delta = (look - lastCameraLook).Magnitude
				cameraMotion = cameraMotion * 0.88 + (delta / math.max(deltaTime, 0.001)) * 0.12
			end
			lastCameraLook = look
		end

		if state.toggles.motionBlur then
			local strength = math.clamp(state.sliders.motionBlurStrength * math.min(cameraMotion * 5, 1), 0, 1)
			for _, streak in ipairs(motionStreaks) do
				streak.BackgroundTransparency = 1 - strength * 0.16
			end
		else
			for _, streak in ipairs(motionStreaks) do
				streak.BackgroundTransparency = 1
			end
		end

		if state.toggles.vhs then
			vhsBand.Position = UDim2.new(0, 0, (clock * 0.09) % 1, 0)
			vhsBand.BackgroundTransparency = 0.85 + math.sin(clock * 24) * 0.07
			vhsRec.TextTransparency = (math.sin(clock * 4) > 0) and 0 or 0.55
			if math.floor(clock) ~= vhsSecond then
				vhsSecond = math.floor(clock)
				vhsTime.Text = localTimeString()
			end
		end

		if state.toggles.reShade and math.floor(clock * 10) ~= reShadeFrame then
			reShadeFrame = math.floor(clock * 10)
			for _, line in ipairs(reShadeGrain) do
				line.Position = UDim2.new(math.random(), 0, math.random(), 0)
			end
		end

		if state.toggles.winterTerrain then
			local intensity = math.clamp(state.sliders.snowIntensity / 100, 0.1, 1)
			local viewport = math.max(overlay.AbsoluteSize.Y, 1)
			for _, flake in ipairs(snowFlakes) do
				flake.y = flake.y + (flake.speed * intensity * deltaTime) / viewport
				if flake.y > 1.05 then
					flake.y = -0.05
					flake.x = math.random()
				end
				flake.frame.Position = UDim2.new(
					flake.x + math.sin(clock * 0.8 + flake.sway) * 0.012,
					0,
					flake.y,
					0
				)
			end
		end

		if state.toggles.angelAura then
			local root = getRootPart()
			if root and (not auraAttachment or auraAttachment.Parent ~= root) then
				ensureAura()
			end
			if auraEmitter and state.dropdowns.auraColor == "Rainbow" then
				local hue = (clock * 0.15 * math.max(state.sliders.auraSpeed, 0.1)) % 1
				local color = Color3.fromHSV(hue, 0.7, 1)
				auraEmitter.Color = ColorSequence.new(color)
				if auraLight then
					auraLight.Color = color
				end
			end
		end

		if state.toggles.motionTrail then
			local root = getRootPart()
			if root and (not trailInstance or trailInstance.Parent ~= root) then
				ensureTrail()
			end
			if trailInstance and state.dropdowns.trailColor == "Rainbow" then
				local color = Color3.fromHSV((clock * 0.2) % 1, 0.7, 1)
				trailInstance.Color = ColorSequence.new(color, color)
			end
		end

		if state.toggles.skyText and skyTextPart then
			local camera = Workspace.CurrentCamera
			if camera then
				local position = camera.CFrame.Position
					+ Vector3.new(0, state.sliders.skyTextHeight, 0)
					+ camera.CFrame.LookVector * state.sliders.skyTextDistance
				local base = CFrame.lookAt(position, camera.CFrame.Position)
				local anim = state.dropdowns.skyTextAnim or "None"
				local speed = math.max(state.sliders.skyTextAnimSpeed or 1, 0.05)
				if anim == "Scroll X" then
					local travel = ((clock * speed * 40) % 800) - 400
					base = base + base.RightVector * travel
				elseif anim == "Scroll Y" then
					local travel = ((clock * speed * 40) % 800) - 400
					base = base + base.UpVector * travel
				elseif anim == "Wave" then
					base = base + base.UpVector * (math.sin(clock * speed * 2) * 30)
				elseif anim == "Rotate" then
					base = base * CFrame.Angles(0, 0, clock * speed)
				end
				local baseSize = math.clamp(state.sliders.skyTextSize, 20, 400)
				local pulse = (anim == "Pulse") and (1 + math.sin(clock * speed * 3) * 0.25) or 1
				skyTextPart.Size = Vector3.new(baseSize * pulse, baseSize * 0.4 * pulse, 0.2)
				skyTextPart.CFrame = base
			end
		end

		if (state.toggles.universalSnow or state.toggles.sparkles) and universalSnowPart then
			local camera = Workspace.CurrentCamera
			if camera then
				universalSnowPart.CFrame = camera.CFrame * CFrame.new(0, 14, 0)
			end
		end

		if state.toggles.rainbow then
			local hue = (clock * 0.08 * math.max(state.sliders.rainbowSpeed, 0.05)) % 1
			local top = Color3.fromHSV(hue, 0.55, 1)
			local bottom = Color3.fromHSV((hue + 0.5) % 1, 0.55, 1)
			safeSet(Lighting, "ColorShift_Top", top)
			safeSet(Lighting, "ColorShift_Bottom", bottom)
			local correction = ensurePost("ColorCorrection")
			if correction then
				safeSet(correction, "TintColor", top)
			end
		end

		if state.toggles.policeFlash then
			local flip = math.sin(clock * (2 + state.sliders.policeFlashSpeed * 3)) > 0
			local color = flip and Color3.fromRGB(255, 48, 48) or Color3.fromRGB(48, 96, 255)
			safeSet(Lighting, "Ambient", color)
			local correction = ensurePost("ColorCorrection")
			if correction then
				safeSet(correction, "TintColor", color)
			end
			local bloom = ensurePost("Bloom")
			if bloom then
				local base = state.base.Bloom and state.base.Bloom.Intensity or 0.4
				safeSet(bloom, "Intensity", base + (flip and 1.1 or 0.15))
			end
		end

		if state.toggles.neon then
			for _, highlight in pairs(neonHighlights) do
				if highlight and highlight.Parent then
					highlight.OutlineColor = Color3.fromHSV((clock * 0.15) % 1, 0.9, 1)
				end
			end
		end

		if state.toggles.windVFX and windVFXEmitter and windVFXPart then
			if camera then
				windVFXPart.CFrame = camera.CFrame * CFrame.new(0, 6, -18)
			end
			local strength = state.sliders.windStrength
			windVFXEmitter.Rate = particleCap(8 + strength * 0.6)
			windVFXEmitter.Speed = NumberRange.new(6 + strength * 0.15, 14 + strength * 0.35)
			local okWind, currentWind = pcall(function()
				return Workspace.GlobalWind
			end)
			if okWind and typeof(currentWind) == "Vector3" then
				safeSet(windVFXEmitter, "Acceleration", currentWind * 1.5)
			end
		end
		end)
		if not ok and not stepErrorLogged then
			stepErrorLogged = true
			warn("[ShaderVelard] RenderStepped error: " .. tostring(err))
		end
	end)

	notifyChanged()
	setStatus("ShaderVelard ready - no key required")

	return Effects
end

-- ===== Module: UI =====
__modules["UI"] = function()
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
