	local TITLE_Y = isMobile and 8 or 11
	local TITLE_SIZE = isMobile and 16 or 18
	local VERSION_Y = isMobile and 24 or 28
	local VERSION_SIZE = isMobile and 9 or 10

	local UI = {}

	local function make(className, properties, parent)
		local instance = Instance.new(className)
		for key, value in pairs(properties or {}) do
			instance[key] = value
		end
		instance.Parent = parent
		return instance
	end

	local function addCorner(instance, radius)
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, radius)
		corner.Parent = instance
		return corner
	end

	local function addStroke(instance, color, thickness, transparency)
		local stroke = Instance.new("UIStroke")
		stroke.Color = color or theme.Stroke
		stroke.Thickness = thickness or 1
		stroke.Transparency = transparency or 0
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		stroke.Parent = instance
		return stroke
	end

	local function addGradient(instance, colorSequence, rotation)
		local gradient = Instance.new("UIGradient")
		gradient.Color = colorSequence
		gradient.Rotation = rotation or 0
		gradient.Parent = instance
		return gradient
	end

	local function tween(instance, info, goals)
		local animation = TweenService:Create(instance, info, goals)
		animation:Play()
		return animation
	end

	-- 8-bit crown sprite. "X" = body pixel, "o" = jewel pixel, "." = empty.
	local CROWN_ART = {
		".X.....X.....X.",
		".X.....X.....X.",
		".XX...XXX...XX.",
		".XXX.XXXXX.XXX.",
		".XXXXXXXXXXXXX.",
		".XXXXXXXXXXXXX.",
		".XoXXoXXoXXoXX.",
		".XXXXXXXXXXXXX.",
		".XXXXXXXXXXXXX.",
		".XXXXXXXXXXXXX.",
		"..XXXXXXXXXXX..",
	}

	local function createPixelCrown(parent, position, pixelSize, bodyColor, jewelColor, zIndex)
		local rows = #CROWN_ART
		local columns = #CROWN_ART[1]
		local crown = make("Frame", {
			Name = "PixelCrown",
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(columns * pixelSize, rows * pixelSize),
			Position = position,
			ZIndex = zIndex or 4,
		}, parent)

		for y = 1, rows do
			local line = CROWN_ART[y]
			for x = 1, columns do
				local glyph = line:sub(x, x)
				local color
				if glyph == "X" then
					color = bodyColor
				elseif glyph == "o" then
					color = jewelColor
				end
				if color then
					make("Frame", {
						Name = string.format("Px_%d_%d", x, y),
						Size = UDim2.fromOffset(pixelSize, pixelSize),
						Position = UDim2.fromOffset((x - 1) * pixelSize, (y - 1) * pixelSize),
						BackgroundColor3 = color,
						BorderSizePixel = 0,
						ZIndex = zIndex or 4,
					}, crown)
				end
			end
		end

		return crown
	end

	-- Prefer CoreGui: many live games' anti-cheat clears unknown ScreenGuis sitting
	-- in PlayerGui, which makes the menu vanish right after it is created. CoreGui
	-- is not touched by that. Fall back to PlayerGui if CoreGui is unavailable.
	local function pickGuiParent()
		local ok, coreGui = pcall(function()
			return game:GetService("CoreGui")
		end)
		if ok and coreGui then
			return coreGui
		end
		return playerGui
	end

	local guiParent = pickGuiParent()
	local previousGui = guiParent:FindFirstChild("ShaderVelardUI")
			or playerGui:FindFirstChild("ShaderVelardUI")
	if previousGui then
		previousGui:Destroy()
	end
	local gui = Instance.new("ScreenGui")
	gui.Name = "ShaderVelardUI"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 200
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	gui.Parent = guiParent

	-- Some games detach/destroy injected guis. If ours is ever removed from the
	-- chosen parent while not intentionally destroyed, re-attach it. The watchdog
	-- stops once UI.destroy() sets UI._destroyed.
	gui.AncestryChanged:Connect(function(_, parent)
		if UI and UI._destroyed then
			return
		end
		if parent ~= guiParent then
			pcall(function()
				gui.Parent = guiParent
			end)
		end
	end)

	local window = make("Frame", {
		Name = "Window",
