			LayoutOrder = #parent:GetChildren(),
		}, parent)
		addCorner(row, 10)
		local rowStroke = addStroke(row, theme.Stroke, 1, 0.25)

		make("TextLabel", {
			Text = label,
			Font = fonts.Medium,
			TextSize = 13,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, description and 8 or 13),
			Size = UDim2.new(1, -86, 0, 16),
		}, row)

		if description then
			make("TextLabel", {
				Text = description,
				Font = fonts.Regular,
				TextSize = 10,
				TextColor3 = theme.SubText,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextWrapped = true,
				BackgroundTransparency = 1,
				Position = UDim2.fromOffset(14, 26),
				Size = UDim2.new(1, -90, 0, 18),
			}, row)
		end

		local track = make("TextButton", {
