		}, row)
		addCorner(track, 13)

		local knob = make("Frame", {
			Name = "Knob",
			Size = UDim2.fromOffset(20, 20),
			Position = UDim2.fromOffset(3, 3),
			BackgroundColor3 = theme.Text,
			BorderSizePixel = 0,
			ZIndex = 6,
		}, track)
		addCorner(knob, 10)

		local function setValue(value)
			value = value == true
			tween(track, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				BackgroundColor3 = value and theme.Accent or theme.Stroke,
			})
			tween(knob, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Position = value and UDim2.fromOffset(25, 3) or UDim2.fromOffset(3, 3),
				BackgroundColor3 = value and Color3.fromRGB(12, 12, 14) or theme.Text,
			})
			rowStroke.Transparency = value and 0 or 0.25
			rowStroke.Color = value and theme.Accent or theme.Stroke
		end

		setValue(Effects.state.toggles[key])
		toggles[key] = { setValue = setValue }

		local lastToggle = 0
		local function toggle()
			local now = os.clock()
			if now - lastToggle < 0.1 then
				return
			end
			lastToggle = now
			local nextValue = not (Effects.state.toggles[key] == true)
			setValue(nextValue)
			local ok, err = pcall(function()
				Effects.setToggle(key, nextValue)
			end)
			if not ok then
				warn("[ShaderVelard] toggle '" .. key .. "' failed: " .. tostring(err))
			end
			setValue(Effects.state.toggles[key])
		end

		row.MouseEnter:Connect(function()
			row.BackgroundColor3 = theme.CardHover
		end)
		row.MouseLeave:Connect(function()
			row.BackgroundColor3 = theme.Card
		end)
		row.Activated:Connect(toggle)
		track.Activated:Connect(toggle)

		return row
	end

