	local notifications = {}
	local function layoutNotifications()
		local index = 0
		for _, entry in ipairs(notifications) do
			if entry.card.Parent then
				entry.card.Position = UDim2.new(1, -18, 0, 16 + index * 74)
				index = index + 1
			end
		end
	end

	local function showNotification(title, content, duration)
		if not interfaceState.notifications then
			return nil
		end
		duration = duration or 4
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
		local cardWidth = isMobile and math.clamp(viewport.X - 32, 170, 280) or 280
		local card = make("Frame", {
			Name = "Notify_" .. tostring(#notifications + 1),
			Size = UDim2.fromOffset(cardWidth, 64),
			Position = UDim2.new(1, -18, 0, 16),
			AnchorPoint = Vector2.new(1, 0),
			BackgroundColor3 = theme.BgSoft,
			BorderSizePixel = 0,
			ZIndex = 490,
		}, gui)
		card.ClipsDescendants = true
		addCorner(card, 12)
		local stroke = addStroke(card, theme.Accent, 1, 0.35)
		local accent = make("Frame", {
			Name = "Accent",
			Size = UDim2.new(0, 3, 0, 40),
			Position = UDim2.fromOffset(0, 12),
			BackgroundColor3 = theme.Accent,
			BorderSizePixel = 0,
			ZIndex = 491,
		}, card)
		addCorner(accent, 2)
		make("TextLabel", {
			Text = title,
			Font = fonts.Bold,
			TextSize = 12,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, 10),
			Size = UDim2.new(1, -24, 0, 16),
			ZIndex = 491,
		}, card)
		make("TextLabel", {
			Text = content,
			Font = fonts.Regular,
			TextSize = 10,
			TextColor3 = theme.SubText,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, 28),
			Size = UDim2.new(1, -24, 0, 30),
			ZIndex = 491,
		}, card)

		local entry = { card = card }
		table.insert(notifications, entry)
		layoutNotifications()
		card.BackgroundTransparency = 1
		local goal = card.BackgroundTransparency
		tween(card, TweenInfo.new(0.2), { BackgroundTransparency = 0 })

		task.delay(duration, function()
			if not card.Parent then
				return
			end
			tween(card, TweenInfo.new(0.25), { BackgroundTransparency = 1 })
			tween(stroke, TweenInfo.new(0.25), { Transparency = 1 })
			task.wait(0.28)
			for index, item in ipairs(notifications) do
				if item == entry then
					table.remove(notifications, index)
					break
				end
			end
			card:Destroy()
			layoutNotifications()
		end)
		return card
	end

	function UI.notify(title, content, duration)
		return showNotification(title, content, duration)
	end

