		layout.Padding = UDim.new(0, 7)
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Parent = scroll
		local scrollPadding = Instance.new("UIPadding")
		scrollPadding.PaddingRight = UDim.new(0, 6)
		scrollPadding.PaddingBottom = UDim.new(0, 8)
		scrollPadding.Parent = scroll

		tabs[name] = { button = button, marker = marker, scroll = scroll, label = label }
		scrollFrames[name] = scroll

		button.Activated:Connect(function()
			closePopup()
			for tabName, tab in pairs(tabs) do
				local selected = tabName == name
				tab.scroll.Visible = selected
				tab.marker.Visible = selected
				tab.button.TextColor3 = selected and theme.Accent or theme.SubText
				tab.button.BackgroundColor3 = selected and theme.Card or theme.BgSoft
				if selected then
					activeTab = tabName
				end
			end
		end)

		return scroll
	end

	local function addKeybind(parent, id, label)
		local row = make("Frame", {
			Name = "Keybind_" .. id,
			Size = UDim2.new(1, 0, 0, 44),
			BackgroundColor3 = theme.Card,
			BorderSizePixel = 0,
			LayoutOrder = #parent:GetChildren(),
		}, parent)
		addCorner(row, 10)
		addStroke(row, theme.Stroke, 1, 0.25)

		make("TextLabel", {
			Text = label,
			Font = fonts.Medium,
			TextSize = 13,
			TextColor3 = theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(14, 14),
			Size = UDim2.new(1, -160, 0, 16),
		}, row)

		local button = make("TextButton", {
			Name = "Key",
			Text = tostring(interfaceState.keybinds[id].Name),
			Font = fonts.Mono,
			TextSize = 12,
			TextColor3 = theme.Accent,
			TextXAlignment = Enum.TextXAlignment.Center,
			BackgroundColor3 = theme.BgSoft,
			AutoButtonColor = false,
			Position = UDim2.new(1, -140, 0, 8),
			Size = UDim2.fromOffset(128, 28),
			BorderSizePixel = 0,
			ZIndex = 5,
		}, row)
		addCorner(button, 8)
		addStroke(button, theme.Stroke, 1, 0.1)

		button.Activated:Connect(function()
			listeningKeybind = id
			button.Text = "Press a key..."
		end)

		keybindButtons[id] = button
		return row
	end

