	local hudAccum = 0
	local hudFrames = 0
	local hudConnection = nil
	function updateHUD()
		if hudFrame then
			hudFrame.Visible = interfaceState.hud == true
		end
	end

	hudConnection = RunService.RenderStepped:Connect(function(deltaTime)
		if UI._destroyed or not interfaceState.hud then
			return
		end
		hudAccum = hudAccum + deltaTime
		hudFrames = hudFrames + 1
		if hudAccum >= 0.5 then
			local fps = math.floor(hudFrames / hudAccum + 0.5)
			hudAccum = 0
			hudFrames = 0
			local ping = 0
			pcall(function()
				ping = math.floor(player:GetNetworkPing() * 1000 + 0.5)
			end)
			hudLabel.Text = string.format("FPS %d   PING %dms", fps, ping)
		end
	end)

	local function dragWithinScreen(guiObject, targetOffsetX, targetOffsetY, allowHalfOffscreen)
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
		local absolute = guiObject.AbsolutePosition
		local size = guiObject.AbsoluteSize
		local predictedX = absolute.X + (targetOffsetX - guiObject.Position.X.Offset)
		local predictedY = absolute.Y + (targetOffsetY - guiObject.Position.Y.Offset)
		local minX, maxX, minY, maxY
		if allowHalfOffscreen then
			minX = -size.X * 0.5
			maxX = viewport.X - size.X * 0.5
			minY = -size.Y * 0.5
			maxY = viewport.Y - size.Y * 0.5
		else
			minX = 0
			maxX = math.max(viewport.X - size.X, 0)
			minY = 0
			maxY = math.max(viewport.Y - size.Y, 0)
		end
		local clampedX = math.clamp(predictedX, minX, maxX)
		local clampedY = math.clamp(predictedY, minY, maxY)
		return targetOffsetX + (clampedX - predictedX), targetOffsetY + (clampedY - predictedY)
	end

	local draggingButton = false
	local dragMoved = false
	local dragStart = Vector2.zero
	local startPosition = UDim2.new()

	floating.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			draggingButton = true
			dragMoved = false
			dragStart = Vector2.new(input.Position.X, input.Position.Y)
			startPosition = floating.Position
		end
	end)

	UserInputService.InputChanged:Connect(function(input)
		if draggingButton and (input.UserInputType == Enum.UserInputType.MouseMovement
			or input.UserInputType == Enum.UserInputType.Touch) then
			local position = Vector2.new(input.Position.X, input.Position.Y)
			local delta = position - dragStart
			if delta.Magnitude > 4 then
				dragMoved = true
			end
			local nextX = startPosition.X.Offset + delta.X
			local nextY = startPosition.Y.Offset + delta.Y
			nextX, nextY = dragWithinScreen(floating, nextX, nextY, true)
			floating.Position = UDim2.fromOffset(nextX, nextY)
		end
	end)

	UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			if draggingButton and not dragMoved then
				setWindowVisible(not window.Visible)
			end
			draggingButton = false
		end
	end)

	closeButton.Activated:Connect(function()
		setWindowVisible(false)
	end)

	minimizeButton.Activated:Connect(function()
		setWindowVisible(false)
	end)

	local draggingWindow = false
	local windowDragStart = Vector2.zero
	local windowStartPosition = UDim2.new()

	header.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			draggingWindow = true
			windowDragStart = Vector2.new(input.Position.X, input.Position.Y)
			windowStartPosition = window.Position
		end
	end)

	UserInputService.InputChanged:Connect(function(input)
		if draggingWindow and (input.UserInputType == Enum.UserInputType.MouseMovement
			or input.UserInputType == Enum.UserInputType.Touch) then
			local position = Vector2.new(input.Position.X, input.Position.Y)
			local delta = position - windowDragStart
			local nextX = windowStartPosition.X.Offset + delta.X
			local nextY = windowStartPosition.Y.Offset + delta.Y
			nextX, nextY = dragWithinScreen(window, nextX, nextY)
			window.Position = UDim2.new(
				windowStartPosition.X.Scale,
				nextX,
				windowStartPosition.Y.Scale,
				nextY
			)
		end
	end)

	UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			draggingWindow = false
		end
	end)

	UserInputService.InputBegan:Connect(function(input, processed)
		if input.UserInputType == Enum.UserInputType.Keyboard and listeningKeybind then
			local id = listeningKeybind
			listeningKeybind = nil
			local button = keybindButtons[id]
			if input.KeyCode == Enum.KeyCode.Escape then
				if button then
					button.Text = tostring(interfaceState.keybinds[id].Name)
				end
				return
			end
			interfaceState.keybinds[id] = input.KeyCode
			if button then
				button.Text = tostring(input.KeyCode.Name)
			end
			showNotification("Hotkey", "Bound to " .. tostring(input.KeyCode.Name))
			return
		end
		if processed then
			return
		end
		if input.UserInputType ~= Enum.UserInputType.Keyboard then
			return
		end
		if input.KeyCode == interfaceState.keybinds.toggleUI then
			setWindowVisible(not window.Visible)
		elseif input.KeyCode == interfaceState.keybinds.resetEffects then
			Effects.resetAll()
			showNotification("ShaderVelard", "All effects reset via hotkey.")
		elseif input.KeyCode == interfaceState.keybinds.toggleHUD then
			interfaceState.hud = not interfaceState.hud
			updateHUD()
		elseif input.KeyCode == Enum.KeyCode.Escape then
			closePopup()
		end
	end)

	function updateScale()
		local camera = workspace.CurrentCamera
		if not camera then
			return
		end
		if isMobile then
			windowScale.Scale = math.clamp(interfaceState.uiScale or 1, 0.6, 1)
			return
		end
		local viewport = camera.ViewportSize
		local scale = math.clamp(math.min(viewport.X / 980, viewport.Y / 720), 0.72, 1.2)
		scale = scale * math.clamp(interfaceState.uiScale or 1, 0.5, 1.5)
		windowScale.Scale = scale
	end
	updateScale()
	workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(updateScale)

	local function refresh()
		for key, widget in pairs(toggles) do
			widget.setValue(Effects.state.toggles[key])
		end
		for key, widget in pairs(sliders) do
			widget.setValue(Effects.state.sliders[key], false)
		end

		if dropdowns.sky then
			dropdowns.sky.setValue(Effects.state.skyName)
		end
		for key, widget in pairs(dropdowns) do
			if key ~= "sky" and Effects.state.dropdowns[key] ~= nil then
				widget.setValue(Effects.state.dropdowns[key])
			end
		end

		presetLabel.Text = "Preset: " .. Effects.state.presetName
		for name, card in pairs(presetCards) do
			local active = Effects.state.presetName == name
			card.stroke.Color = active and theme.Accent or theme.Stroke
			card.stroke.Transparency = active and 0 or 0.3
			card.accent.BackgroundColor3 = active and theme.Accent or theme.Stroke
			card.card.BackgroundColor3 = theme.Card
		end
	end

	local refreshPending = false
	local function requestRefresh()
		if refreshPending or UI._destroyed then
			return
		end
		refreshPending = true
		task.delay(0.08, function()
			refreshPending = false
			if not UI._destroyed then
				refresh()
			end
		end)
	end

	Effects.onChanged = requestRefresh
	Effects.onStatus = function(message)
		statusLabel.Text = message
	end
	Effects.onNotify = function(title, content, duration)
		showNotification(title, content, duration)
	end
	Effects.onSkyChanged = function(name)
		if dropdowns.sky then
			dropdowns.sky.setValue(name)
		end
	end

	UI.show = function()
		UI.setVisible(true)
	end

	UI.hide = function()
		UI.setVisible(false)
	end

	UI.applyPreset = function(name)
		Effects.applyPreset(name)
		showNotification("Preset Applied", tostring(name))
	end

	UI.setSky = function(name)
		Effects.applySky(name)
	end

	UI.getState = function()
		return Effects.state
	end

	UI.destroy = function()
		if UI._destroyed then
			return
		end
		UI._destroyed = true
		Effects.onChanged = nil
		Effects.onStatus = nil
		Effects.onNotify = nil
		Effects.onSkyChanged = nil
		if hudConnection then
			hudConnection:Disconnect()
			hudConnection = nil
		end
		if gui and gui.Parent then
			gui:Destroy()
		end
	end

	UI.window = window

	applyIconStyle()
	applyGuiStyle()
	setWindowVisible(true)
	statusLabel.Text = "Ready - client-side only, no key required"
	refresh()
	showNotification("ShaderVelard", "Loaded " .. Config.Version .. ". Press RightShift to toggle.", 5)

	return UI
end

-- ===== Bootstrap =====
local function __shaderVelardPickGuiParent()
	local ok, coreGui = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok and coreGui then
		return coreGui
	end
	local p = game:GetService("Players").LocalPlayer
	return p and p:WaitForChild("PlayerGui")
end

local function __shaderVelardMarker(title, body, color)
	pcall(function()
		local parent = __shaderVelardPickGuiParent()
		if not parent then
			return
		end
		local old = parent:FindFirstChild("ShaderVelardLoadError")
		if old then
			old:Destroy()
		end
		local gui = Instance.new("ScreenGui")
		gui.Name = "ShaderVelardLoadError"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.DisplayOrder = 1000
		gui.Parent = parent
		local label = Instance.new("TextLabel")
		label.AnchorPoint = Vector2.new(0.5, 0.5)
		label.Position = UDim2.fromScale(0.5, 0.5)
		label.Size = UDim2.fromOffset(560, 240)
		label.BackgroundColor3 = Color3.fromRGB(20, 20, 24)
		label.BackgroundTransparency = 0.1
		label.TextColor3 = color
		label.TextWrapped = true
		label.Font = Enum.Font.Code
		label.TextSize = 14
		label.Text = title .. "\n\n" .. body
		label.Parent = gui
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, 10)
		corner.Parent = label
	end)
end

local __bootOk, __bootResult = pcall(function()
	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local Players = game:GetService("Players")

	local player = Players.LocalPlayer
	if player then
		player:WaitForChild("PlayerGui")
	end

	local previousApi = nil
	pcall(function()
		previousApi = shared.ShaderVelard
	end)
	if not previousApi then
		pcall(function()
			previousApi = _G.ShaderVelard
		end)
	end
	if previousApi and type(previousApi.Destroy) == "function" then
		pcall(function()
			previousApi.Destroy()
		end)
	end

	local Config = __require("Config")

	local UI = __require("UI")
	local Effects = __require("Effects")

	local API = {}

	function API.SetToggle(name, value)
		Effects.setToggle(name, value == true)
	end

	function API.SetSlider(name, value)
		if type(value) ~= "number" then
			return
		end
		Effects.setSlider(name, value)
	end

	function API.SetDropdown(name, value)
		Effects.setDropdown(name, value)
	end

	function API.ApplyPreset(name)
		Effects.applyPreset(name)
	end

	function API.SetSkybox(name)
		Effects.applySky(name)
	end

	function API.Reset()
		Effects.resetAll()
	end

	function API.SetLiteMode(value)
		return Effects.setLiteMode(value)
	end

	function API.Destroy()
		pcall(function()
			if UI.destroy then
				UI.destroy()
			end
		end)
		pcall(function()
			if Effects.destroy then
				Effects.destroy()
			end
		end)
		pcall(function()
			shared.ShaderVelard = nil
		end)
		pcall(function()
			_G.ShaderVelard = nil
		end)
	end

	function API.ShowUI()
		UI.show()
	end

	function API.HideUI()
		UI.hide()
	end

	function API.ToggleUI()
		return UI.toggle()
	end

	function API.Notify(title, content, duration)
		return UI.notify(title, content, duration)
	end

	function API.GetState()
		return Effects.state
	end

	function API.GetPresets()
		return Effects.getPresetNames()
	end

	function API.GetSkyboxes()
		return Effects.getSkyNames()
	end

	API.Version = Config.Version
	API.Config = Config
	API.Effects = Effects
	API.UI = UI

	pcall(function()
		shared.ShaderVelard = API
	end)
	pcall(function()
		_G.ShaderVelard = API
	end)
	if script and script.Parent then
		pcall(function()
			script.Parent:SetAttribute("ShaderVelardVersion", Config.Version)
		end)
	end

	return UI
end)

if not __bootOk then
	local text = tostring(__bootResult)
	warn("[ShaderVelard] LOAD ERROR: " .. text)
	__shaderVelardMarker("ShaderVelard failed to load:", text, Color3.fromRGB(255, 90, 90))
else
	local version = tostring(__bootResult and __bootResult.Version or "n/a")
	print("[ShaderVelard] loaded OK (" .. version .. ")")
	__shaderVelardMarker("ShaderVelard loaded OK (" .. version .. ")",
		"If the main menu is not visible, it was removed by the game. This marker lives in CoreGui.",
		Color3.fromRGB(120, 255, 140))
	task.delay(6, function()
		pcall(function()
			local parent = __shaderVelardPickGuiParent()
			local m = parent and parent:FindFirstChild("ShaderVelardLoadError")
			if m then
				m:Destroy()
			end
		end)
	end)
end
